# Generated by Selenium IDE / Pytest for SGCS Project
import pytest
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

class TestRegister:
    def setup_method(self, method):
        # Configure and maximize Chrome browser
        options = webdriver.ChromeOptions()
        options.add_argument("--start-maximized")
        self.driver = webdriver.Chrome(options=options)
        self.wait = WebDriverWait(self.driver, 10)  # Explicit wait

    def teardown_method(self, method):
        self.driver.quit()

    def test_register(self):
        # Step 1: Navigate to registration page
        self.driver.get("http://localhost:5173/register")

        # Step 2: Enter valid Full Name
        fullname_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "register-fullname-field"))
        )
        fullname_field.clear()
        fullname_field.send_keys("Rahul Sharma")

        # Step 3: Enter valid Email Address
        email_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "register-email-field"))
        )
        email_field.clear()
        email_field.send_keys("test_citizen@example.com")

        # Step 4: Enter valid Mobile Phone
        phone_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "register-phone-field"))
        )
        phone_field.clear()
        phone_field.send_keys("9876543210")

        # Step 5: Enter Residential Address
        address_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "register-address-field"))
        )
        address_field.clear()
        address_field.send_keys("Flat 402, Green Valley, Ward 1")

        # Step 6: Enter Password
        password_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "register-password-field"))
        )
        password_field.clear()
        password_field.send_keys("Citizen@123")

        # Step 7: Enter Confirm Password
        confirm_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "register-confirmpassword-field"))
        )
        confirm_field.clear()
        confirm_field.send_keys("Citizen@123")

        # Step 8: Agree to Terms checkbox
        terms_checkbox = self.wait.until(
            EC.presence_of_element_located((By.ID, "register-agree-checkbox"))
        )
        if not terms_checkbox.is_selected():
            self.driver.execute_script("arguments[0].click();", terms_checkbox)

        # Step 9: Click Register button
        register_btn = self.wait.until(
            EC.element_to_be_clickable((By.CSS_SELECTOR, "button[type='submit']"))
        )
        register_btn.click()

        # Step 10: Verify registration completed successfully and user is navigated to dashboard
        self.wait.until(
            lambda d: "/dashboard" in d.current_url or len(d.find_elements(By.XPATH, "//*[contains(text(), 'Registration Completed')]")) > 0
        )
        assert "/dashboard" in self.driver.current_url or "Registration Completed" in self.driver.page_source, "Registration failed to complete"
        time.sleep(3)

if __name__ == "__main__":
    pytest.main(["-v", __file__])
